suspend fun dashboard(): Dashboard = coroutineScope {
    val user = async { loadUser() }
    val orders = async { loadOrders() }
    Dashboard(user.await(), orders.await())
}

suspend fun refreshWidgets() = supervisorScope {
    val weather = async { runCatching { loadWeather() } }
    val news = async { runCatching { loadNews() } }
    weather.await() to news.await()
}
